    void SetUp() override {
        std::snprintf(origin, 100, "%s%d", ORIGIN, rand() % 12345 + 123);
        std::snprintf(result, 100, "%s%d", RESULT, rand() % 12345 + 123);
        create_random(2);
    }

    void TearDown() override {
        std::remove(origin);
        std::remove(result);
    }
};

